package codehub.core.permissions

object DangerousCommandPatterns {

    data class DangerousMatch(
        val patternKey: String,
        val description: String,
        val severity: Severity
    )

    enum class Severity { Warn, Dangerous, Catastrophic }

    data class Pattern(
        val key: String,
        val regex: Regex,
        val description: String,
        val severity: Severity
    )

    val patterns: List<Pattern> = listOf(
        Pattern("rm_rf_root", Regex("""\brm\s+(?:-[a-zA-Z]*r[a-zA-Z]*f?|-[a-zA-Z]*f[a-zA-Z]*r)\s+(?:--no-preserve-root\s+)?/(?:\s|$|\*)"""), "Recursive delete targeting filesystem root", Severity.Catastrophic),
        Pattern("rm_rf_home", Regex("""\brm\s+(?:-[a-zA-Z]*r[a-zA-Z]*f?|-[a-zA-Z]*f[a-zA-Z]*r)\s+(?:~|${'$'}HOME)(?:\s|$)"""), "Recursive delete of home directory", Severity.Catastrophic),
        Pattern("rm_rf_wildcard", Regex("""\brm\s+(?:-[a-zA-Z]*r[a-zA-Z]*f?|-[a-zA-Z]*f[a-zA-Z]*r)\s+\*\.(?:so|apk|dex|jar|class|o|a|exe)"""), "Recursive delete of build artifacts", Severity.Dangerous),
        Pattern("rm_force_no_prompt", Regex("""\brm\s+.*-f.*\s"""), "Forced file deletion without prompt", Severity.Warn),
        Pattern("mkfs_any", Regex("""\bmkfs(?:\.\w+)?\s+/dev/(?:sd|nvme|vd|hd|mmcblk)"""), "Filesystem format on block device", Severity.Catastrophic),
        Pattern("dd_to_device", Regex("""\bdd\s+if=.*\s+of=/dev/(?:sd|nvme|vd|hd|mmcblk)"""), "Raw write to block device", Severity.Catastrophic),
        Pattern("dd_from_dev", Regex("""\bdd\s+if=/dev/(?:sd|nvme|vd|hd|mmcblk)"""), "Raw read from block device", Severity.Dangerous),
        Pattern("chmod_777", Regex("""\bchmod\s+(?:-R\s+)?777\b"""), "World-writable recursive chmod", Severity.Warn),
        Pattern("chmod_777_path", Regex("""\bchmod\s+(?:-R\s+)?777\s+/(?:etc|usr|bin|sbin|system|boot|root)"""), "chmod 777 on system path", Severity.Catastrophic),
        Pattern("chown_root", Regex("""\bchown\s+(?:-R\s+)?root(?::\w+)?\s+/(?:etc|usr|bin|sbin|system)"""), "Recursive chown to root on system path", Severity.Dangerous),
        Pattern("curl_pipe_sh", Regex("""\b(?:curl|wget)\s+(?:-[a-zA-Z]+\s+)*https?://[^\s|]+\s*\|\s*(?:sh|bash|zsh|python(?:3)?|perl)\b"""), "Remote script piped to interpreter", Severity.Catastrophic),
