        Pattern("wget_pipe_sh", Regex("""\bwget\s+(?:-[a-zA-Z]+\s+)*-O\s+-\s+https?://[^\s|]+\s*\|\s*(?:sh|bash)"""), "Wget output piped to shell", Severity.Catastrophic),
