    fun evaluate(command: String): DangerousMatch? {
        for (pattern in patterns) {
            if (pattern.regex.containsMatchIn(command)) {
                return DangerousMatch(
                    patternKey = pattern.key,
                    description = pattern.description,
                    severity = pattern.severity
                )
            }
        }
        return null
    }

    fun isDangerous(command: String): Boolean = evaluate(command) != null

    val catastrophicPatternKeys: Set<String> = patterns
        .filter { it.severity == Severity.Catastrophic }
        .map { it.key }
        .toSet()

    val dangerousPatternKeys: Set<String> = patterns
        .filter { it.severity == Severity.Dangerous }
        .map { it.key }
        .toSet()
}
